<?php
$edit=null;if(isset($_GET['edit'])){$q=db()->prepare('SELECT * FROM expenses WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$q=db()->prepare('SELECT e.*,u.name recorded_name FROM expenses e LEFT JOIN users u ON u.id=e.recorded_by WHERE e.expense_date BETWEEN ? AND ? ORDER BY e.expense_date DESC,e.id DESC');$q->execute([$from,$to]);$rows=$q->fetchAll();$total=array_sum(array_map(fn($r)=>(float)$r['amount'],$rows));
?>
<div class="page-heading"><div><div class="eyebrow">Operating costs</div><h1>Expenses</h1><p>Record business spending and monitor net income.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#expenseModal"><i class="bi bi-plus-lg me-1"></i>Record expense</button></div>
<div class="row g-3 mb-3"><div class="col-md-4"><div class="card stat-card"><div class="stat-label">Expenses in selected period</div><div class="stat-value text-danger"><?=money($total)?></div><div class="stat-foot"><?=count($rows)?> records</div></div></div></div>
<div class="card"><div class="card-body border-bottom"><form class="row g-2 align-items-end"><input type="hidden" name="page" value="expenses"><div class="col-md-4"><label class="form-label">From</label><input class="form-control" name="from" type="date" value="<?=h($from)?>"></div><div class="col-md-4"><label class="form-label">To</label><input class="form-control" name="to" type="date" value="<?=h($to)?>"></div><div class="col-md-2"><button class="btn btn-outline-secondary w-100">Filter</button></div></form></div><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Expense</th><th>Category</th><th>Payment method</th><th>Recorded by</th><th>Amount</th><th></th></tr></thead><tbody><?php if(!$rows)echo table_empty(7);foreach($rows as $r):?><tr><td><?=date_label($r['expense_date'])?></td><td><strong><?=h($r['description'])?></strong><div class="small-muted"><?=h($r['expense_code'])?> <?=h($r['notes'])?></div></td><td><?=h(ucwords($r['category']))?></td><td><?=h(strtoupper(str_replace('_',' ',$r['payment_method'])))?></td><td><?=h($r['recorded_name']??'—')?></td><td class="fw-bold"><?=money($r['amount'])?></td><td class="text-end"><a class="btn btn-sm btn-light" href="<?=h(app_page_url('expenses',['edit'=>$r['id'],'from'=>$from,'to'=>$to]))?>"><i class="bi bi-pencil"></i></a> <?=post_form_start('delete_expense',app_page_url('expenses',['from'=>$from,'to'=>$to]))?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-light text-danger" data-confirm="Delete this expense record?"><i class="bi bi-trash"></i></button></form></td></tr><?php endforeach;?></tbody></table></div></div>
<div class="modal fade" id="expenseModal" tabindex="-1"><div class="modal-dialog"><div class="modal-content"><?=post_form_start('save_expense',app_page_url('expenses',['from'=>$from,'to'=>$to]))?><div class="modal-header"><h5 class="modal-title"><?=$edit?'Edit expense':'Record expense'?></h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><?php if($edit):?><input type="hidden" name="id" value="<?=$edit['id']?>"><?php endif;?><div class="mb-3"><label class="form-label">Description *</label><input class="form-control" name="description" required value="<?=h($edit['description']??'')?>"></div><div class="row g-3"><div class="col-6"><label class="form-label">Category</label><select class="form-select" name="category"><?php foreach(['supplies','utilities','rent','salaries','maintenance','marketing','other'] as $v):?><option value="<?=$v?>" <?=selected($edit['category']??'other',$v)?>><?=ucwords($v)?></option><?php endforeach;?></select></div><div class="col-6"><label class="form-label">Amount (₱) *</label><input class="form-control" type="number" name="amount" min="0.01" step="0.01" required value="<?=h($edit['amount']??'')?>"></div><div class="col-6"><label class="form-label">Date *</label><input class="form-control" type="date" name="expense_date" required value="<?=h($edit['expense_date']??date('Y-m-d'))?>"></div><div class="col-6"><label class="form-label">Payment method</label><select class="form-select" name="payment_method"><?php foreach(['cash','gcash','bank_transfer','other'] as $v):?><option value="<?=$v?>" <?=selected($edit['payment_method']??'cash',$v)?>><?=ucwords(str_replace('_',' ',$v))?></option><?php endforeach;?></select></div><div class="col-12"><label class="form-label">Notes</label><textarea class="form-control" name="notes"><?=h($edit['notes']??'')?></textarea></div></div></div><div class="modal-footer"><a href="<?=h(app_page_url('expenses'))?>" class="btn btn-light">Cancel</a><button class="btn btn-primary">Save expense</button></form></div></div></div></div><?php if($edit):?><script>document.addEventListener('DOMContentLoaded',()=>new bootstrap.Modal(document.getElementById('expenseModal')).show());</script><?php endif;?>
